   labels             → addLabel (Sample / Magnetic field / Electromagnets)
─────────────────────────────────────────────────────────────────────────── */

const GOLD = 0xE4CE3B, GOLD_D = 0xB39A22, GOLD_L = 0xF5E98A;
const STEEL = 0x9A9A9A, PURPLE = 0x8A3FD1;
const tmpV = new THREE.Vector3();
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

/* ── lighting (hemisphere + key from upper-left) ─────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xcfcfcf, 1.0));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-6, 8, 7);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.35);
fillLight.position.set(5, 2, -6);
scene.add(fillLight);

/* ── materials ───────────────────────────────────────────────────────────── */
const goldMat = new THREE.MeshStandardMaterial({ color: GOLD, roughness: 0.32, metalness: 0.55 });
const goldDark = new THREE.MeshStandardMaterial({ color: GOLD_D, roughness: 0.4, metalness: 0.5 });
const steelMat = new THREE.MeshStandardMaterial({ color: STEEL, roughness: 0.35, metalness: 0.72 });
const steelLite = new THREE.MeshStandardMaterial({ color: 0xD9D9D9, roughness: 0.3, metalness: 0.7 });
const blackMat = new THREE.MeshStandardMaterial({ color: 0x151515, roughness: 0.7, metalness: 0.1 });
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xCFE6E8, roughness: 0.05, metalness: 0.0, transmission: 0.9, thickness: 0.3,
  transparent: true, opacity: 0.38, side: THREE.DoubleSide, depthWrite: false
});
const sampleMat = new THREE.MeshStandardMaterial({ color: 0x6B83E8, roughness: 0.3, metalness: 0.1 });
const meniscusMat = new THREE.MeshStandardMaterial({ color: 0x93A9F2, roughness: 0.3 });
const inkMat = new THREE.LineBasicMaterial({ color: 0x000000 });
const fieldMat = new THREE.MeshBasicMaterial({ color: PURPLE, transparent: true, opacity: 0.95 });

function addEdges(mesh, threshold = 25) {
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry, threshold), inkMat);
  mesh.add(e);
  return mesh;
}
function rod(a, b, r, material) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), material);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
