base.position.set(1.6, -3.3, 0);
stand.add(addEdges(base));

const column = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.15, 7.2, 28), goldMat);
column.position.set(1.6, 0.3, 0);
