/* ── BALANCE GROUP (pivots about the fulcrum at (1.6, 4.15, 0)) ──────────── */
const PIVOT = new THREE.Vector3(1.6, 4.15, 0);
const balance = new THREE.Group();
balance.position.copy(PIVOT);
scene.add(balance);

// beam: world x -2.6 .. 3.4  ->  local -4.2 .. 1.8
const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 6.0, 20), goldMat);
beam.rotation.z = Math.PI / 2;
beam.position.set(-1.2, 0, 0);
balance.add(addEdges(beam, 40));

function hook(x) {
  const t = new THREE.Mesh(new THREE.TorusGeometry(0.13, 0.05, 10, 26, Math.PI * 1.5), goldMat);
  t.position.set(x, 0.12, 0);
  t.rotation.z = Math.PI * 0.75;
  balance.add(t);
  return t;
}
hook(-4.2);
hook(1.8);

/* ── LEFT ARM: thread + sample tube (stays plumb) ────────────────────────── */
const leftHang = new THREE.Group();
leftHang.position.set(-4.2, 0, 0);      // world origin (-2.6, 4.15, 0)
balance.add(leftHang);
const leftPlumb = new THREE.Group();
leftHang.add(leftPlumb);

leftPlumb.add(rod(new THREE.Vector3(0, 0.04, 0), new THREE.Vector3(0, -1.25, 0), 0.02, blackMat));

const tubeGroup = new THREE.Group();
