tubeBody.position.y = -2.95;
tubeBody.renderOrder = 3;
tubeGroup.add(tubeBody);

const tubeBottom = new THREE.Mesh(
  new THREE.SphereGeometry(0.28, 32, 14, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glassMat);
