      pts.push(new THREE.Vector3(CX + a * Math.cos(phi), CY + sgn * b * Math.sin(phi), 0));
    }
    const curve = addTube(pts, 0.022);
    const ts = i < 2 ? [0.5] : [0.2, 0.5, 0.8];
    ts.forEach(t => addArrowAt(curve.getPointAt(t), curve.getTangentAt(t), 1));
  });
}

// 3. outward fans near the far ends of each pole
function fan(cx, angles, radii, inward) {
  angles.forEach(deg => {
    radii.forEach(r => {
      const a = THREE.MathUtils.degToRad(deg);
      const dirOut = new THREE.Vector3(Math.cos(a), Math.sin(a), 0);
      const p0 = new THREE.Vector3(cx + dirOut.x * r, CY + dirOut.y * r, 0);
      const dir = inward ? dirOut.clone().negate() : dirOut.clone();
      const p1 = p0.clone().add(dir.clone().multiplyScalar(0.42));
      addTube([p0, p0.clone().lerp(p1, 0.5), p1], 0.018);
      addArrowAt(p1, dir, 0.8);
    });
  });
}
