    B: 1.5, sample: 'dia'
  }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  proc = null;
  setSample(s.sample);
  Btarget = s.B;
  slider.value = s.B;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narration;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── UPDATE LOOP ─────────────────────────────────────────────────────────── */
let lastRead = -1;
function update() {
  requestAnimationFrame(update);

  if (proc) {
    const t = (performance.now() - proc.t0) / 1000;
    if (t < 1) { Btarget = 1.0 * t; procStatus = 'field ramping up…'; }
    else if (t < 2) { Btarget = 1.0; procStatus = 'beam deflecting…'; }
    else if (t < 3) {
      Btarget = 1.0;
      counterTarget = clamp(t - 2, 0, 1);
      extraWeight.visible = true;
      extraWeight.scale.setScalar(0.4 + 0.6 * counterTarget);
      procStatus = 'adding counterweights…';
    } else {
      counterTarget = 1; procStatus = 'balanced — Δm locked in'; proc = null;
    }
    slider.value = Btarget.toFixed(2);
  }

  Bcur += (Btarget - Bcur) * 0.18;
  counterCur += (counterTarget - counterCur) * 0.10;

  const chiEff = state.sample === 'para' ? CHI_PARA : CHI_DIA * DIA_EXAG;
  const chiTrue = state.sample === 'para' ? CHI_PARA : CHI_DIA;
  const tiltTarget = clamp(K_TILT * chiEff * Bcur * Bcur, -9, 9) * (1 - counterCur);
  tiltCur += (tiltTarget - tiltCur) * 0.12;

  balance.rotation.z = THREE.MathUtils.degToRad(tiltCur);
  leftPlumb.rotation.z = -balance.rotation.z;
  rightPlumb.rotation.z = -balance.rotation.z;

  const vis = clamp(Bcur / 0.55, 0, 1);
  fieldMat.opacity = 0.95 * vis;
  fieldMat.visible = vis > 0.015;
  const flow = 1 + 0.08 * Math.sin(performance.now() * 0.006);
  for (const a of arrowHeads) a.scale.setScalar((0.35 + 0.75 * vis) * a.userData.baseScale * flow);

  sampleLabel.pos.copy(sampleAnchor.getWorldPosition(tmpV));

  bVal.textContent = Bcur.toFixed(2);

  const F = chiTrue * AREA * Bcur * Bcur / (2 * MU0);       // newtons
  const dm_mg = (F / G) * 1e6;                              // milligrams
  const rounded = Math.round(dm_mg);
  if (rounded !== lastRead || proc || Math.abs(Btarget - Bcur) > 1e-3) {
    lastRead = rounded;
    const chiStr = state.sample === 'para' ? '+1.5×10⁻³ (paramagnetic)' : '−2.0×10⁻⁵ (diamagnetic)';
    readout.textContent =
      `B        = ${Bcur.toFixed(2)} T\n` +
      `χ        = ${chiStr}\n` +
      `F        = χAB²/2μ₀\n` +
      `Δm       = ${rounded >= 0 ? '+' : ''}${rounded} mg  ${rounded > 0 ? '(heavier)' : rounded < 0 ? '(lighter)' : '(balanced)'}\n` +
      `beam     = ${tiltCur >= 0 ? 'tube side DOWN' : 'tube side UP'} ${Math.abs(tiltCur).toFixed(1)}°` +
      (state.sample === 'dia' ? '  [tilt ×20 exaggerated]' : '') +
      (procStatus ? `\nstatus   = ${procStatus}` : '');
  }
}
update();

goToStep(1);          // start energized so the figure matches the printed diagram
Bcur = 0.8;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

