// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ─────────────────────────────────────────────────────────
   base disc          → CylinderGeometry(1.2,1.15,0.18,56)        bright gold #EFD94E + dark edges
   column             → CylinderGeometry(0.13,0.15,7.2,28)         bright gold
   fulcrum triangle   → ConeGeometry(0.26,0.42,4)                  gold
   balance beam       → CylinderGeometry(0.075,0.075,6.0) rot z    gold
   beam hooks (x2)    → TorusGeometry(0.13,0.05,…,1.5π)            gold
   suspension thread  → rod cylinder r=0.02                        black
   sample tube        → CylinderGeometry(0.32,0.32,3.4,open)+hemi  pale-cyan glass + white rim/strip
   tube lip ring      → TorusGeometry(0.38,0.055)                  glass
   blue sample        → CylinderGeometry(0.29)+hemisphere          #5F7BEE, meniscus #93A9F2
   pan cords (x3)     → rod cylinders r=0.016                      black
   weighing pan       → LatheGeometry dish (r 0.95) + rim Torus    bright gold, DoubleSide
   calibrated weights → CylinderGeometry(0.2,0.2,0.42) x3 (+1)     light steel #DCE0E4 + edges
   magnet poles (x2)  → CylinderGeometry(0.75,0.75,1.7) rot z=π/2  light steel #C6C6C6 + black edges
   pole collars (x2)  → CylinderGeometry(0.82,0.82,0.25) rot z=π/2 lighter steel #E9E9E9
   gap field arrows   → rod tubes + ConeGeometry heads (26)        purple #8A3FD1
   fringing loops     → elongated ellipses hugging the gap, split
                        where they meet the poles (Tube on curve)  purple
   pole-edge fans     → dense arrows on top+bottom of both poles   purple
   end fans           → short arrows off each pole's outer end     purple
   leader lines       → THREE.Line                                 black
   labels             → addLabel (Sample / Magnetic field / Electromagnets)
─────────────────────────────────────────────────────────────────────────── */

const GOLD = 0xEFD94E, GOLD_D = 0xC0A524, PURPLE = 0x8A3FD1;
const tmpV = new THREE.Vector3();
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

/* ── lighting: bright, flat, cartoon-like (low metalness, no env map) ────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.85));
scene.add(new THREE.HemisphereLight(0xffffff, 0xe8e8e8, 0.85));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.75);
keyLight.position.set(-6, 8, 9);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.35);
fillLight.position.set(6, 2, -6);
scene.add(fillLight);

/* ── materials ───────────────────────────────────────────────────────────── */
const goldMat = new THREE.MeshStandardMaterial({
  color: GOLD, roughness: 0.45, metalness: 0.12, emissive: 0x4a4110
});
const goldDark = new THREE.MeshStandardMaterial({
  color: GOLD_D, roughness: 0.5, metalness: 0.12, emissive: 0x38300c
});
const goldPan = new THREE.MeshStandardMaterial({
  color: 0xF3E066, roughness: 0.45, metalness: 0.1, emissive: 0x554a12, side: THREE.DoubleSide
});
const steelMat = new THREE.MeshStandardMaterial({
  color: 0xC6C6C6, roughness: 0.5, metalness: 0.2, emissive: 0x262626
});
const steelLite = new THREE.MeshStandardMaterial({
  color: 0xE9E9E9, roughness: 0.45, metalness: 0.18, emissive: 0x2c2c2c
});
const weightMat = new THREE.MeshStandardMaterial({
  color: 0xDDE1E5, roughness: 0.4, metalness: 0.22, emissive: 0x2a2c2f
});
const blackMat = new THREE.MeshStandardMaterial({ color: 0x151515, roughness: 0.8, metalness: 0.0 });
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xDCF0F2, roughness: 0.06, metalness: 0.0, transmission: 0.55, thickness: 0.3,
  transparent: true, opacity: 0.34, side: THREE.DoubleSide, depthWrite: false
});
const sampleMat = new THREE.MeshStandardMaterial({
  color: 0x5F7BEE, roughness: 0.35, metalness: 0.05, emissive: 0x101b45
});
const meniscusMat = new THREE.MeshStandardMaterial({ color: 0x93A9F2, roughness: 0.35, emissive: 0x18224a });
const whiteMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.85 });
const inkMat = new THREE.LineBasicMaterial({ color: 0x000000 });
const goldEdge = new THREE.LineBasicMaterial({ color: 0x8A7615 });
const glassEdge = new THREE.LineBasicMaterial({ color: 0x86B9C2 });
const fieldMat = new THREE.MeshBasicMaterial({ color: PURPLE, transparent: true, opacity: 0.95 });

function addEdges(mesh, threshold = 25, mat = inkMat) {
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry, threshold), mat));
  return mesh;
}
function rod(a, b, r, material) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), material);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
function line3(points, material = inkMat) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), material);
}

/* ── STAND ───────────────────────────────────────────────────────────────── */
const stand = new THREE.Group();
scene.add(stand);

const base = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.15, 0.18, 56), goldMat);
base.position.set(1.6, -3.3, 0);
stand.add(addEdges(base, 25, goldEdge));

const column = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.15, 7.2, 28), goldMat);
column.position.set(1.6, 0.3, 0);
stand.add(addEdges(column, 40, goldEdge));

const fulcrum = new THREE.Mesh(new THREE.ConeGeometry(0.26, 0.42, 4), goldDark);
fulcrum.position.set(1.6, 3.94, 0);
fulcrum.rotation.y = Math.PI / 4;
stand.add(addEdges(fulcrum, 20, goldEdge));

/* ── BALANCE GROUP (pivots about the fulcrum at (1.6, 4.15, 0)) ──────────── */
const PIVOT = new THREE.Vector3(1.6, 4.15, 0);
const balance = new THREE.Group();
balance.position.copy(PIVOT);
scene.add(balance);

const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 6.0, 20), goldMat);
beam.rotation.z = Math.PI / 2;
beam.position.set(-1.2, 0, 0);
balance.add(addEdges(beam, 40, goldEdge));

function hook(x) {
  const t = new THREE.Mesh(new THREE.TorusGeometry(0.13, 0.05, 10, 26, Math.PI * 1.5), goldMat);
  t.position.set(x, 0.12, 0);
  t.rotation.z = Math.PI * 0.75;
  balance.add(t);
  return t;
}
hook(-4.2);
hook(1.8);

/* ── LEFT ARM: thread + glass sample tube (stays plumb) ──────────────────── */
const leftHang = new THREE.Group();
leftHang.position.set(-4.2, 0, 0);          // world (-2.6, 4.15, 0)
balance.add(leftHang);
const leftPlumb = new THREE.Group();
leftHang.add(leftPlumb);

leftPlumb.add(rod(new THREE.Vector3(0, 0.04, 0), new THREE.Vector3(0, -1.25, 0), 0.02, blackMat));

const tubeGroup = new THREE.Group();
leftPlumb.add(tubeGroup);

const TUBE_R = 0.32;
const tubeBody = new THREE.Mesh(
  new THREE.CylinderGeometry(TUBE_R, TUBE_R, 3.4, 36, 1, true), glassMat);
tubeBody.position.y = -2.95;
tubeBody.renderOrder = 6;
tubeGroup.add(tubeBody);
tubeBody.add(new THREE.LineSegments(new THREE.EdgesGeometry(tubeBody.geometry, 25), glassEdge));

const tubeBottom = new THREE.Mesh(
  new THREE.SphereGeometry(TUBE_R, 32, 16, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glassMat);
tubeBottom.position.y = -4.65;
tubeBottom.renderOrder = 6;
tubeGroup.add(tubeBottom);

const tubeLip = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.06, 12, 36), glassMat);
tubeLip.rotation.x = Math.PI / 2;
tubeLip.position.y = -1.25;
tubeLip.renderOrder = 6;
tubeGroup.add(tubeLip);
const lipRing = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.02, 8, 40), whiteMat);
lipRing.rotation.x = Math.PI / 2;
lipRing.position.y = -1.22;
lipRing.renderOrder = 7;
tubeGroup.add(lipRing);

const rimHi = new THREE.Mesh(new THREE.TorusGeometry(TUBE_R, 0.022, 8, 36), whiteMat);
rimHi.rotation.x = Math.PI / 2;
rimHi.position.y = -1.27;
rimHi.renderOrder = 7;
tubeGroup.add(rimHi);

// vertical specular strip so the glass reads against the field lines
const strip = new THREE.Mesh(new THREE.PlaneGeometry(0.07, 3.1), whiteMat);
strip.position.set(-0.14, -2.95, 0.29);
strip.renderOrder = 7;
tubeGroup.add(strip);

// blue sample: lower 65 % of the tube
const SAMP_H = 3.4 * 0.65;
const sampleCol = new THREE.Mesh(new THREE.CylinderGeometry(0.29, 0.29, SAMP_H, 30), sampleMat);
sampleCol.position.y = -4.65 + SAMP_H / 2;
tubeGroup.add(sampleCol);
const sampleBot = new THREE.Mesh(
  new THREE.SphereGeometry(0.29, 30, 14, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), sampleMat);
sampleBot.position.y = -4.65;
tubeGroup.add(sampleBot);
const meniscus = new THREE.Mesh(new THREE.CylinderGeometry(0.29, 0.29, 0.07, 30), meniscusMat);
meniscus.position.y = -4.65 + SAMP_H;
tubeGroup.add(meniscus);

/* ── RIGHT ARM: cords + pan + weights (stays plumb) ──────────────────────── */
const rightHang = new THREE.Group();
rightHang.position.set(1.8, 0, 0);
balance.add(rightHang);
const rightPlumb = new THREE.Group();
rightHang.add(rightPlumb);

const panGroup = new THREE.Group();
panGroup.position.y = -1.55;
rightPlumb.add(panGroup);

const PAN_R = 0.95;
const panProfile = [];
for (let i = 0; i <= 12; i++) {
  const u = i / 12;
  panProfile.push(new THREE.Vector2(0.02 + PAN_R * u, -0.07 + 0.29 * u * u));
}
const pan = new THREE.Mesh(new THREE.LatheGeometry(panProfile, 60), goldPan);
panGroup.add(pan);
const panRim = new THREE.Mesh(new THREE.TorusGeometry(PAN_R, 0.055, 10, 60), goldMat);
panRim.rotation.x = Math.PI / 2;
panRim.position.y = 0.22;
panGroup.add(panRim);

[95, 215, 335].forEach(deg => {
  const a = THREE.MathUtils.degToRad(deg);
  const p = new THREE.Vector3(PAN_R * Math.cos(a), -1.55 + 0.22, PAN_R * Math.sin(a));
  rightPlumb.add(rod(new THREE.Vector3(0, 0.02, 0), p, 0.016, blackMat));
});

function weight(x, z) {
  const w = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.42, 26), weightMat);
  w.position.set(x, 0.2, z);
  panGroup.add(addEdges(w, 40));
  const knob = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.09, 0.1, 18), steelLite);
  knob.position.y = 0.26;
  w.add(knob);
  return w;
}
weight(-0.26, 0.16);
weight(0.26, 0.02);
weight(0.00, -0.28);
const extraWeight = weight(-0.42, -0.24);
extraWeight.visible = false;

/* ── ELECTROMAGNET POLES ─────────────────────────────────────────────────── */
const magnets = new THREE.Group();
scene.add(magnets);
const CX = -2.6, CY = 0.15, R_POLE = 0.75, POLE_HALF = 0.85;

function pole(cx, collarX) {
  const g = new THREE.Group();
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(R_POLE, R_POLE, 1.7, 44), steelMat);
  cyl.rotation.z = Math.PI / 2;
  cyl.position.set(cx, CY, 0);
  g.add(addEdges(cyl, 40));
  const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.82, 0.82, 0.25, 44), steelLite);
  collar.rotation.z = Math.PI / 2;
  collar.position.set(collarX, CY, 0);
  g.add(addEdges(collar, 40));
  magnets.add(g);
  return g;
}
const leftPole = pole(-4.25, -3.62);    // spans x −5.10 … −3.40
const rightPole = pole(-0.95, -1.68);   // spans x −1.80 … −0.10
const POLE_SPANS = [[-5.10, -3.40], [-1.80, -0.10]];

/* ── MAGNETIC FIELD ──────────────────────────────────────────────────────── */
const fieldGroup = new THREE.Group();
scene.add(fieldGroup);
const arrowHeads = [];
const coneGeo = new THREE.ConeGeometry(0.075, 0.2, 12);

function addArrowAt(pos, dir, s = 1) {
  const c = new THREE.Mesh(coneGeo, fieldMat);
  c.position.copy(pos);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  c.userData.baseScale = s;
  fieldGroup.add(c);
  arrowHeads.push(c);
  return c;
}
function addTube(points, radius = 0.021) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, Math.max(20, points.length * 3), radius, 6, false);
  fieldGroup.add(new THREE.Mesh(geo, fieldMat));
  return curve;
}
function seg(p0, p1, r = 0.02) {
  fieldGroup.add(rod(p0.clone(), p1.clone(), r, fieldMat));
}

// 1 ── dense short arrows crossing the gap, split around the tube
for (let i = 0; i < 13; i++) {
  const y = CY - 0.70 + i * (1.40 / 12);
  const a0 = new THREE.Vector3(-3.36, y, 0), a1 = new THREE.Vector3(-3.02, y, 0);
  seg(a0, a1, 0.018);
  addArrowAt(a1, new THREE.Vector3(1, 0, 0), 0.8);
  const b0 = new THREE.Vector3(-2.20, y, 0), b1 = new THREE.Vector3(-1.92, y, 0);
  seg(b0, b1, 0.018);
  addArrowAt(b1, new THREE.Vector3(1, 0, 0), 0.8);
}

// 2 ── elongated fringing loops hugging the gap, cut where they meet the poles
function insidePole(x, y) {
  if (Math.abs(y - CY) > R_POLE * 0.98) return false;
  for (const [x0, x1] of POLE_SPANS) if (x > x0 - 0.02 && x < x1 + 0.02) return true;
  return false;
}
for (let i = 0; i < 7; i++) {
  const a = 0.95 + i * 0.40;
  [1, -1].forEach(sgn => {
    const b = sgn > 0 ? (1.15 + i * 0.25) : (1.00 + i * 0.20);
    const N = 90, runs = [];
    let cur = [];
    for (let k = 0; k <= N; k++) {
      const phi = Math.PI - Math.PI * (k / N);            // π (left) → 0 (right)
      const x = CX + a * Math.cos(phi);
      const y = CY + sgn * b * Math.sin(phi);
      if (insidePole(x, y)) { if (cur.length > 3) runs.push(cur); cur = []; }
      else cur.push(new THREE.Vector3(x, y, 0));
    }
    if (cur.length > 3) runs.push(cur);
    runs.forEach(pts => {
      const curve = addTube(pts, 0.022);
      const ts = pts.length > 45 ? [0.18, 0.5, 0.82] : [0.55];
      ts.forEach(t => addArrowAt(curve.getPointAt(t), curve.getTangentAt(t), 1));
    });
  });
}

// 3 ── dense arrow fans along the top and bottom edges of BOTH poles
function poleEdgeFan(cx, sgn, outward) {
  const n = 8;
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n;
    const x = cx - POLE_HALF + t * 2 * POLE_HALF;
    const surf = new THREE.Vector3(x, CY + sgn * R_POLE * 0.95, 0);
    const lean = clamp((x - CX) / 2.6, -1, 1) * 0.8;
    const out = new THREE.Vector3(lean, sgn, 0).normalize();
    const L = 0.58;
    if (outward) {
      const tip = surf.clone().add(out.clone().multiplyScalar(L));
      seg(surf, tip.clone().sub(out.clone().multiplyScalar(0.12)), 0.018);
      addArrowAt(tip, out, 0.85);
    } else {
      const start = surf.clone().add(out.clone().multiplyScalar(L));
      const tip = surf.clone().add(out.clone().multiplyScalar(0.06));
      seg(start, tip.clone().add(out.clone().multiplyScalar(0.12)), 0.018);
      addArrowAt(tip, out.clone().negate(), 0.85);
    }
  }
}
poleEdgeFan(-4.25, 1, true);
poleEdgeFan(-4.25, -1, true);
poleEdgeFan(-0.95, 1, false);
poleEdgeFan(-0.95, -1, false);

// 4 ── fans off the far ends of each pole
function endFan(cx, angles, radii, inward) {
  angles.forEach(deg => {
    radii.forEach(r => {
      const a = THREE.MathUtils.degToRad(deg);
      const out = new THREE.Vector3(Math.cos(a), Math.sin(a), 0);
      const p0 = new THREE.Vector3(cx + out.x * r, CY + out.y * r, 0);
      const dir = inward ? out.clone().negate() : out.clone();
      const p1 = p0.clone().add(dir.clone().multiplyScalar(0.44));
      seg(p0, p1.clone().sub(dir.clone().multiplyScalar(0.1)), 0.018);
      addArrowAt(p1, dir, 0.8);
    });
  });
}
endFan(-5.05, [125, 152, 180, 208, 235], [1.15, 1.75], true);
endFan(-0.20, [-55, -25, 0, 25, 55], [1.15, 1.75], false);

/* ── LEADER LINES ────────────────────────────────────────────────────────── */
const sampleLeader = line3([
  new THREE.Vector3(-1.32, -1.95, 0),
  new THREE.Vector3(-0.30, -2.45, 0)
]);
leftPlumb.add(sampleLeader);
const sampleAnchor = new THREE.Object3D();
sampleAnchor.position.set(-2.00, -1.92, 0);
