function addEdges(mesh, threshold = 25, mat = inkMat) {
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry, threshold), mat));
  return mesh;
}
function rod(a, b, r, material) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), material);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return m;
}
