const tubeBottom = new THREE.Mesh(
  new THREE.SphereGeometry(TUBE_R, 32, 16, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glassMat);
tubeBottom.position.y = -4.65;
tubeBottom.renderOrder = 6;
tubeGroup.add(tubeBottom);

const tubeLip = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.06, 12, 36), glassMat);
tubeLip.rotation.x = Math.PI / 2;
tubeLip.position.y = -1.25;
tubeLip.renderOrder = 6;
