const lipRing = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.02, 8, 40), whiteMat);
lipRing.rotation.x = Math.PI / 2;
lipRing.position.y = -1.22;
lipRing.renderOrder = 7;
