const SAMP_H = 3.4 * 0.65;
const sampleCol = new THREE.Mesh(new THREE.CylinderGeometry(0.29, 0.29, SAMP_H, 30), sampleMat);
sampleCol.position.y = -4.65 + SAMP_H / 2;
