/* ── RIGHT ARM: cords + pan + weights (stays plumb) ──────────────────────── */
const rightHang = new THREE.Group();
rightHang.position.set(1.8, 0, 0);
balance.add(rightHang);
const rightPlumb = new THREE.Group();
rightHang.add(rightPlumb);

const panGroup = new THREE.Group();
panGroup.position.y = -1.55;
rightPlumb.add(panGroup);

const PAN_R = 0.95;
const panProfile = [];
for (let i = 0; i <= 12; i++) {
  const u = i / 12;
  panProfile.push(new THREE.Vector2(0.02 + PAN_R * u, -0.07 + 0.29 * u * u));
}
const pan = new THREE.Mesh(new THREE.LatheGeometry(panProfile, 60), goldPan);
panGroup.add(pan);
const panRim = new THREE.Mesh(new THREE.TorusGeometry(PAN_R, 0.055, 10, 60), goldMat);
panRim.rotation.x = Math.PI / 2;
panRim.position.y = 0.22;
panGroup.add(panRim);

[95, 215, 335].forEach(deg => {
  const a = THREE.MathUtils.degToRad(deg);
  const p = new THREE.Vector3(PAN_R * Math.cos(a), -1.55 + 0.22, PAN_R * Math.sin(a));
  rightPlumb.add(rod(new THREE.Vector3(0, 0.02, 0), p, 0.016, blackMat));
});

function weight(x, z) {
  const w = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.42, 26), weightMat);
  w.position.set(x, 0.2, z);
  panGroup.add(addEdges(w, 40));
  const knob = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.09, 0.1, 18), steelLite);
  knob.position.y = 0.26;
  w.add(knob);
  return w;
}
weight(-0.26, 0.16);
weight(0.26, 0.02);
weight(0.00, -0.28);
const extraWeight = weight(-0.42, -0.24);
extraWeight.visible = false;

/* ── ELECTROMAGNET POLES ─────────────────────────────────────────────────── */
const magnets = new THREE.Group();
scene.add(magnets);
const CX = -2.6, CY = 0.15, R_POLE = 0.75, POLE_HALF = 0.85;

function pole(cx, collarX) {
  const g = new THREE.Group();
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(R_POLE, R_POLE, 1.7, 44), steelMat);
  cyl.rotation.z = Math.PI / 2;
  cyl.position.set(cx, CY, 0);
  g.add(addEdges(cyl, 40));
  const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.82, 0.82, 0.25, 44), steelLite);
  collar.rotation.z = Math.PI / 2;
  collar.position.set(collarX, CY, 0);
  g.add(addEdges(collar, 40));
  magnets.add(g);
  return g;
}
const leftPole = pole(-4.25, -3.62);    // spans x −5.10 … −3.40
const rightPole = pole(-0.95, -1.68);   // spans x −1.80 … −0.10
const POLE_SPANS = [[-5.10, -3.40], [-1.80, -0.10]];

/* ── MAGNETIC FIELD ──────────────────────────────────────────────────────── */
const fieldGroup = new THREE.Group();
scene.add(fieldGroup);
const arrowHeads = [];
const coneGeo = new THREE.ConeGeometry(0.075, 0.2, 12);

function addArrowAt(pos, dir, s = 1) {
  const c = new THREE.Mesh(coneGeo, fieldMat);
  c.position.copy(pos);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  c.userData.baseScale = s;
  fieldGroup.add(c);
  arrowHeads.push(c);
  return c;
}
function addTube(points, radius = 0.021) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, Math.max(20, points.length * 3), radius, 6, false);
  fieldGroup.add(new THREE.Mesh(geo, fieldMat));
  return curve;
}
function seg(p0, p1, r = 0.02) {
  fieldGroup.add(rod(p0.clone(), p1.clone(), r, fieldMat));
}

// 1 ── dense short arrows crossing the gap, split around the tube
for (let i = 0; i < 13; i++) {
  const y = CY - 0.70 + i * (1.40 / 12);
  const a0 = new THREE.Vector3(-3.36, y, 0), a1 = new THREE.Vector3(-3.02, y, 0);
  seg(a0, a1, 0.018);
  addArrowAt(a1, new THREE.Vector3(1, 0, 0), 0.8);
  const b0 = new THREE.Vector3(-2.20, y, 0), b1 = new THREE.Vector3(-1.92, y, 0);
  seg(b0, b1, 0.018);
  addArrowAt(b1, new THREE.Vector3(1, 0, 0), 0.8);
}

// 2 ── elongated fringing loops hugging the gap, cut where they meet the poles
function insidePole(x, y) {
  if (Math.abs(y - CY) > R_POLE * 0.98) return false;
  for (const [x0, x1] of POLE_SPANS) if (x > x0 - 0.02 && x < x1 + 0.02) return true;
  return false;
}
for (let i = 0; i < 7; i++) {
  const a = 0.95 + i * 0.40;
  [1, -1].forEach(sgn => {
    const b = sgn > 0 ? (1.15 + i * 0.25) : (1.00 + i * 0.20);
    const N = 90, runs = [];
    let cur = [];
    for (let k = 0; k <= N; k++) {
      const phi = Math.PI - Math.PI * (k / N);            // π (left) → 0 (right)
      const x = CX + a * Math.cos(phi);
      const y = CY + sgn * b * Math.sin(phi);
      if (insidePole(x, y)) { if (cur.length > 3) runs.push(cur); cur = []; }
      else cur.push(new THREE.Vector3(x, y, 0));
    }
    if (cur.length > 3) runs.push(cur);
    runs.forEach(pts => {
      const curve = addTube(pts, 0.022);
      const ts = pts.length > 45 ? [0.18, 0.5, 0.82] : [0.55];
      ts.forEach(t => addArrowAt(curve.getPointAt(t), curve.getTangentAt(t), 1));
    });
  });
}

// 3 ── dense arrow fans along the top and bottom edges of BOTH poles
function poleEdgeFan(cx, sgn, outward) {
  const n = 8;
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n;
    const x = cx - POLE_HALF + t * 2 * POLE_HALF;
    const surf = new THREE.Vector3(x, CY + sgn * R_POLE * 0.95, 0);
    const lean = clamp((x - CX) / 2.6, -1, 1) * 0.8;
    const out = new THREE.Vector3(lean, sgn, 0).normalize();
    const L = 0.58;
    if (outward) {
      const tip = surf.clone().add(out.clone().multiplyScalar(L));
      seg(surf, tip.clone().sub(out.clone().multiplyScalar(0.12)), 0.018);
      addArrowAt(tip, out, 0.85);
    } else {
      const start = surf.clone().add(out.clone().multiplyScalar(L));
      const tip = surf.clone().add(out.clone().multiplyScalar(0.06));
      seg(start, tip.clone().add(out.clone().multiplyScalar(0.12)), 0.018);
      addArrowAt(tip, out.clone().negate(), 0.85);
    }
  }
}
poleEdgeFan(-4.25, 1, true);
poleEdgeFan(-4.25, -1, true);
poleEdgeFan(-0.95, 1, false);
poleEdgeFan(-0.95, -1, false);

// 4 ── fans off the far ends of each pole
function endFan(cx, angles, radii, inward) {
  angles.forEach(deg => {
    radii.forEach(r => {
      const a = THREE.MathUtils.degToRad(deg);
      const out = new THREE.Vector3(Math.cos(a), Math.sin(a), 0);
      const p0 = new THREE.Vector3(cx + out.x * r, CY + out.y * r, 0);
      const dir = inward ? out.clone().negate() : out.clone();
      const p1 = p0.clone().add(dir.clone().multiplyScalar(0.44));
      seg(p0, p1.clone().sub(dir.clone().multiplyScalar(0.1)), 0.018);
      addArrowAt(p1, dir, 0.8);
    });
  });
}
endFan(-5.05, [125, 152, 180, 208, 235], [1.15, 1.75], true);
endFan(-0.20, [-55, -25, 0, 25, 55], [1.15, 1.75], false);

/* ── LEADER LINES ────────────────────────────────────────────────────────── */
const sampleLeader = line3([
  new THREE.Vector3(-1.32, -1.95, 0),
  new THREE.Vector3(-0.30, -2.45, 0)
]);
leftPlumb.add(sampleLeader);
const sampleAnchor = new THREE.Object3D();
sampleAnchor.position.set(-2.00, -1.92, 0);
leftPlumb.add(sampleAnchor);

scene.add(line3([new THREE.Vector3(-0.80, 2.72, 0), new THREE.Vector3(-1.70, 1.85, 0)]));
scene.add(line3([new THREE.Vector3(-2.90, -2.78, 0), new THREE.Vector3(-4.25, -1.02, 0)]));
scene.add(line3([new THREE.Vector3(-2.90, -2.78, 0), new THREE.Vector3(-1.05, -1.02, 0)]));

/* ── CAMERA (orthographic axonometric, near front-on like the source) ────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 2, z: 34 },
  rollDeg: 0,
  heightFraction: 0.72
});

/* ── LABELS ──────────────────────────────────────────────────────────────── */
const sampleLabel = addLabel('Sample', new THREE.Vector3(-4.60, 2.25, 0), { fontSize: '15px' });
addLabel('Magnetic<br>field', new THREE.Vector3(-0.20, 3.15, 0), { fontSize: '15px' });
addLabel('Electromagnets', new THREE.Vector3(-2.90, -3.12, 0), { fontSize: '15px' });

/* ── HOVER / CLICK EXPLANATIONS ──────────────────────────────────────────── */
registerInteractive(beam, {
  title: 'Balance beam',
  tooltip: 'Balance beam — pivots on the fulcrum',
  body: 'The beam pivots on the knife-edge fulcrum. Any extra downward force on the sample tube tips the left arm down; counterweights added to the right pan bring it back to level, and the mass added equals the apparent mass change.'
});
registerInteractive(tubeGroup, {
  title: 'Sample tube',
  tooltip: 'Sample tube hanging in the gap',
  body: 'A uniform-bore glass tube packed with the sample hangs so that its lower half sits in the narrow, strongly inhomogeneous part of the field while its top is essentially field-free. Only the sample in the gap feels a force.'
});
registerInteractive(leftPole, {
  title: 'Electromagnet (left pole)',
  tooltip: 'Electromagnet pole piece',
  body: 'A soft-iron pole piece wound with a current-carrying coil. The field between the two faces is intense and strongly non-uniform — that field gradient is what produces a net force on the sample.'
});
registerInteractive(rightPole, {
  title: 'Electromagnet (right pole)',
  tooltip: 'Electromagnet pole piece',
  body: 'The opposite pole. Field lines leave the left face, cross the gap, and enter this face; outside the gap they loop back around the magnet.'
});
registerInteractive(fieldGroup, {
  title: 'Magnetic field',
  tooltip: 'Inhomogeneous magnetic field',
  body: 'Field lines crowd together in the gap (strong B) and spread far apart above, below, and beyond the poles (weak B). A paramagnetic sample is pulled toward the crowded region; a diamagnetic one is pushed toward the sparse region.'
});
registerInteractive(panGroup, {
  title: 'Counterweights',
  tooltip: 'Calibrated weights in the pan',
  body: 'Calibrated masses are added or removed until the beam re-levels. The change needed is the apparent mass change Δm, from which the susceptibility χ is calculated.'
});
registerInteractive(column, {
  title: 'Balance stand',
  tooltip: 'Stand and fulcrum column',
  body: 'The rigid stand holds the fulcrum at a fixed height so the only thing that can move the beam is a change in the forces on its two arms.'
});

/* ── STATE + PHYSICS ─────────────────────────────────────────────────────── */
const CHI_PARA = 1.5e-3;
const CHI_DIA = -2.0e-5;
const DIA_EXAG = 20;
const K_TILT = 2667;
const AREA = 1.0e-4;
const MU0 = 4 * Math.PI * 1e-7;
const G = 9.81;

const state = { sample: 'para' };
let Btarget = 0.8, Bcur = 0.8;
let counterTarget = 0, counterCur = 0;
let tiltCur = 0;
let proc = null;
let procStatus = '';

const slider = document.getElementById('fieldStrength');
const bVal = document.getElementById('bVal');
const readout = document.getElementById('readout');
const btnPara = document.getElementById('btnPara');
const btnDia = document.getElementById('btnDia');
const btnRun = document.getElementById('btnRun');

function resetCounter() {
  counterTarget = 0;
  extraWeight.visible = false;
  procStatus = '';
}
function setSample(kind) {
  state.sample = kind;
  btnPara.classList.toggle('active', kind === 'para');
  btnDia.classList.toggle('active', kind === 'dia');
  sampleMat.color.set(kind === 'para' ? 0x5F7BEE : 0xA8B8E4);
  meniscusMat.color.set(kind === 'para' ? 0x93A9F2 : 0xCBD5EE);
  resetCounter();
}
btnPara.addEventListener('click', () => setSample('para'));
btnDia.addEventListener('click', () => setSample('dia'));

slider.addEventListener('input', () => {
  proc = null;
  Btarget = parseFloat(slider.value);
  resetCounter();
});

btnRun.addEventListener('click', () => {
  proc = { t0: performance.now() };
  Btarget = 0; Bcur = 0; counterTarget = 0; counterCur = 0;
  extraWeight.visible = false;
  procStatus = 'field off — taring…';
});

/* ── GUIDED DEMO ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · Magnets off — beam level',
    narration: 'With no current in the electromagnets the tube feels only gravity. The counterweights exactly balance it and the beam sits horizontal: this is the zero-field reference mass.',
    B: 0, sample: 'para'
  },
  {
    title: '2 · Energize the field',
    narration: 'Current flows and purple field lines crowd the narrow gap. The paramagnetic sample is drawn down into the strongest part of the inhomogeneous field, so the left arm dips — the sample appears heavier.',
    B: 0.8, sample: 'para'
  },
  {
    title: '3 · Stronger field, larger pull',
    narration: 'Doubling the field roughly quadruples the force (F ∝ χB²). The deflection grows, but the susceptibility read out from the added counterweight is unchanged — it is a property of the substance, not of the magnet.',
    B: 1.5, sample: 'para'
  },
  {
    title: '4 · Swap in a diamagnetic sample',
    narration: 'With all electrons paired the sample is weakly expelled from the gap. The left arm rises instead of falling and χ flips sign, and the effect is far smaller than the paramagnetic case (shown ×20 here).',
    B: 1.5, sample: 'dia'
  }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  proc = null;
  setSample(s.sample);
  Btarget = s.B;
  slider.value = s.B;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narration;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── PER-FRAME UPDATE (driven by the scaffold's own render loop) ─────────── */
let lastRead = NaN;
let errCount = 0;

function tick() {
  if (proc) {
    const t = (performance.now() - proc.t0) / 1000;
    if (t < 1) { Btarget = 1.0 * t; procStatus = 'field ramping up…'; }
    else if (t < 2) { Btarget = 1.0; procStatus = 'beam deflecting…'; }
    else if (t < 3) {
      Btarget = 1.0;
      counterTarget = clamp(t - 2, 0, 1);
      extraWeight.visible = true;
      extraWeight.scale.setScalar(0.4 + 0.6 * counterTarget);
      procStatus = 'adding counterweights…';
    } else {
      counterTarget = 1; procStatus = 'balanced — Δm locked in'; proc = null;
    }
    slider.value = Btarget.toFixed(2);
  }

  Bcur += (Btarget - Bcur) * 0.18;
  counterCur += (counterTarget - counterCur) * 0.10;

  const chiEff = state.sample === 'para' ? CHI_PARA : CHI_DIA * DIA_EXAG;
  const chiTrue = state.sample === 'para' ? CHI_PARA : CHI_DIA;
  const tiltTarget = clamp(K_TILT * chiEff * Bcur * Bcur, -9, 9) * (1 - counterCur);
  tiltCur += (tiltTarget - tiltCur) * 0.12;

  balance.rotation.z = THREE.MathUtils.degToRad(tiltCur);
  leftPlumb.rotation.z = -balance.rotation.z;
  rightPlumb.rotation.z = -balance.rotation.z;

  const vis = clamp(Bcur / 0.55, 0, 1);
  fieldMat.opacity = 0.95 * vis;
  fieldMat.visible = vis > 0.015;
  const flow = 1 + 0.08 * Math.sin(performance.now() * 0.006);
  for (let i = 0; i < arrowHeads.length; i++) {
    const a = arrowHeads[i];
    a.scale.setScalar((0.35 + 0.75 * vis) * a.userData.baseScale * flow);
  }

  sampleLabel.pos.copy(sampleAnchor.getWorldPosition(tmpV));
  bVal.textContent = Bcur.toFixed(2);

  const F = chiTrue * AREA * Bcur * Bcur / (2 * MU0);
  const dm_mg = (F / G) * 1e6;
  const rounded = Math.round(dm_mg);
  if (rounded !== lastRead || proc || Math.abs(Btarget - Bcur) > 1e-3) {
    lastRead = rounded;
    const chiStr = state.sample === 'para' ? '+1.5×10⁻³ (paramagnetic)' : '−2.0×10⁻⁵ (diamagnetic)';
    readout.textContent =
      `B        = ${Bcur.toFixed(2)} T\n` +
      `χ        = ${chiStr}\n` +
      `F        = χAB²/2μ₀\n` +
      `Δm       = ${rounded >= 0 ? '+' : ''}${rounded} mg  ${rounded > 0 ? '(heavier)' : rounded < 0 ? '(lighter)' : '(balanced)'}\n` +
      `beam     = ${tiltCur >= 0 ? 'tube side DOWN' : 'tube side UP'} ${Math.abs(tiltCur).toFixed(1)}°` +
      (state.sample === 'dia' ? '  [tilt ×20 exaggerated]' : '') +
      (procStatus ? `\nstatus   = ${procStatus}` : '');
  }
}

// Hook into the scaffold's render loop; errors are swallowed so the loop can
// never freeze.
scene.onBeforeRender = function () {
  try { tick(); }
  catch (e) { if (errCount++ < 3) console.error('figure update:', e); }
};

goToStep(1);          // start energized so the figure matches the printed diagram
Bcur = 0.8;
// @FIGURE_CODE_END

