const magnets = new THREE.Group();
scene.add(magnets);
const CX = -2.6, CY = 0.15, R_POLE = 0.75, POLE_HALF = 0.85;

function pole(cx, collarX) {
  const g = new THREE.Group();
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(R_POLE, R_POLE, 1.7, 44), steelMat);
  cyl.rotation.z = Math.PI / 2;
  cyl.position.set(cx, CY, 0);
  g.add(addEdges(cyl, 40));
  const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.82, 0.82, 0.25, 44), steelLite);
  collar.rotation.z = Math.PI / 2;
  collar.position.set(collarX, CY, 0);
  g.add(addEdges(collar, 40));
  magnets.add(g);
  return g;
}
const leftPole = pole(-4.25, -3.62);    // spans x −5.10 … −3.40
const rightPole = pole(-0.95, -1.68);   // spans x −1.80 … −0.10
const POLE_SPANS = [[-5.10, -3.40], [-1.80, -0.10]];

/* ── MAGNETIC FIELD ──────────────────────────────────────────────────────── */
const fieldGroup = new THREE.Group();
scene.add(fieldGroup);
const arrowHeads = [];
const coneGeo = new THREE.ConeGeometry(0.07, 0.18, 12);

function addArrowAt(pos, dir, s = 1) {
  const c = new THREE.Mesh(coneGeo, fieldMat);
  c.position.copy(pos);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  c.userData.baseScale = s;
  fieldGroup.add(c);
  arrowHeads.push(c);
  return c;
}
function addTube(points, radius = 0.019) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, Math.max(16, points.length * 2), radius, 6, false);
  fieldGroup.add(new THREE.Mesh(geo, fieldMat));
  return curve;
}
function seg(p0, p1, r = 0.018) {
  fieldGroup.add(rod(p0.clone(), p1.clone(), r, fieldMat));
}

// 1 ── dense short arrows crossing the gap, split around the tube (left → right)
for (let i = 0; i < 13; i++) {
  const y = CY - 0.70 + i * (1.40 / 12);
  seg(new THREE.Vector3(-3.38, y, 0), new THREE.Vector3(-3.04, y, 0), 0.017);
  addArrowAt(new THREE.Vector3(-3.00, y, 0), new THREE.Vector3(1, 0, 0), 0.75);
  seg(new THREE.Vector3(-2.24, y, 0), new THREE.Vector3(-1.92, y, 0), 0.017);
  addArrowAt(new THREE.Vector3(-1.88, y, 0), new THREE.Vector3(1, 0, 0), 0.75);
}

// 2 ── 6 nested fringing arcs above + 6 below, clipped by the pole silhouettes
function insidePole(x, y) {
  if (Math.abs(y - CY) > 0.78) return false;
  for (const [x0, x1] of POLE_SPANS) if (x > x0 - 0.02 && x < x1 + 0.02) return true;
  return false;
}
for (let i = 0; i < 6; i++) {
  const a = 0.85 + i * 0.42;                       // 0.85 … 2.95
  [1, -1].forEach(sgn => {
    const b = sgn > 0 ? (0.95 + i * 0.33) : (0.85 + i * 0.27);   // top → 2.60, bottom → 2.20
    const N = 80, runs = [];
    let cur = [];
    for (let k = 0; k <= N; k++) {
      const phi = Math.PI - Math.PI * (k / N);      // π (left) → 0 (right): flux L → R
      const x = CX + a * Math.cos(phi);
      const y = CY + sgn * b * Math.sin(phi);
      if (insidePole(x, y)) { if (cur.length > 4) runs.push(cur); cur = []; }
      else cur.push(new THREE.Vector3(x, y, 0));
    }
    if (cur.length > 4) runs.push(cur);
    runs.forEach(pts => {
      const curve = addTube(pts, 0.019);
      const ts = pts.length > 34 ? [0.3, 0.72] : [0.55];
      ts.forEach(t => addArrowAt(curve.getPointAt(t), curve.getTangentAt(t), 0.95));
    });
  });
}

// 3 ── arrow fans on the top/bottom edges of both poles
//      left pole = N: flux leaves the surface · right pole = S: flux enters it
function poleEdgeFan(cx, sgn, outward) {
  const n = 5, L = 0.50;
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n;
    const x = cx - POLE_HALF + t * 2 * POLE_HALF;
    const surf = new THREE.Vector3(x, CY + sgn * R_POLE * 0.95, 0);
    const lean = clamp((x - CX) / 2.6, -1, 1) * 0.7;
    const out = new THREE.Vector3(lean, sgn, 0).normalize();
    if (outward) {
      const tip = surf.clone().add(out.clone().multiplyScalar(L));
      seg(surf, tip.clone().sub(out.clone().multiplyScalar(0.12)), 0.017);
      addArrowAt(tip, out, 0.8);
    } else {
      const start = surf.clone().add(out.clone().multiplyScalar(L));
      const tip = surf.clone().add(out.clone().multiplyScalar(0.06));
      seg(start, tip.clone().add(out.clone().multiplyScalar(0.12)), 0.017);
      addArrowAt(tip, out.clone().negate(), 0.8);
    }
  }
}
poleEdgeFan(-4.25, 1, true);
poleEdgeFan(-4.25, -1, true);
poleEdgeFan(-0.95, 1, false);
poleEdgeFan(-0.95, -1, false);

// 4 ── fans off the far ends: left pole outward (flux leaving N),
//      right pole inward (flux returning into S) — consistent with the gap sense
function endFan(cx, angles, radii, inward) {
  angles.forEach(deg => {
    radii.forEach(r => {
      const a = THREE.MathUtils.degToRad(deg);
      const out = new THREE.Vector3(Math.cos(a), Math.sin(a), 0);
      const p0 = new THREE.Vector3(cx + out.x * r, CY + out.y * r, 0);
      const dir = inward ? out.clone().negate() : out.clone();
      const p1 = p0.clone().add(dir.clone().multiplyScalar(0.40));
      seg(p0, p1.clone().sub(dir.clone().multiplyScalar(0.10)), 0.017);
      addArrowAt(p1, dir, 0.78);
    });
  });
}
endFan(-5.08, [135, 165, 195, 225], [1.05, 1.60], false);   // leaving the left (N) pole
endFan(-0.16, [-45, -15, 15, 45], [1.05, 1.60], true);      // entering the right (S) pole

